const band = (x1 - x0) / days.length;
const bw = Math.min(BAR_MAX, band - GAP);
const worst = days.reduce((a, b) => (b.bal_de_keur ?? 0) < (a.bal_de_keur ?? 0) ? b : a, days[0]);
const labels = labelIndices(days.length, x1 - x0);

days.forEach((d, i) => {
  const v = d.bal_de_keur ?? 0, up = v >= 0;
  const cx = x0 + band * (i + .5), top = Math.min(y(v), y(0));
  svg.append(el("path", {
    d: barPath(cx - bw / 2, top, bw, Math.abs(y(v) - y(0)), RAD, up),
    fill: up ? "var(--in)" : "var(--out)",
  }));
  // hit target spans the whole band, so it clears the 24px minimum
  const hit = el("rect", { class: "hit", x: cx - band / 2, y: y0, width: band, height: PLOT_H });
  hit.addEventListener("pointerenter", e => showTip(e, tipRows(d)));
  hit.addEventListener("pointermove", e => showTip(e, tipRows(d)));
  hit.addEventListener("pointerleave", hideTip);
  svg.append(hit);

  if (d === worst) {                     // label the extreme only, never every bar
    svg.append(el("text", { class: "val", x: cx, y: y(v) + (v < 0 ? 14 : -7),
                            "text-anchor": "middle" }, money(v)));
  }
  if (labels.has(i)) {
    svg.append(el("text", { x: cx, y: y1 + 17, "text-anchor": "middle" }, dLabel(d.date)));

