    const thru = Math.min(d.transit_gwh ?? 0, d.import_gwh ?? 0, d.export_gwh ?? 0);
    const stack = (total, up, mine) => {
      const own = Math.max(0, total - thru);
      const dir = up ? -1 : 1;
      // inner segment: square both ends, it meets the axis and the next segment
      if (own > 0) {
        const hp = h(own);
        svg.append(el("rect", { x: cx - bw / 2, y: up ? mid - hp : mid,
                                width: bw, height: hp, fill: mine }));
      }
      // outer segment: rounded on the data end only, held off by the surface gap
      if (thru > 0) {
        const base = mid + dir * (h(own) + GAP);
        const hp = Math.max(0, h(thru) - GAP);
        svg.append(el("path", { d: barPath(cx - bw / 2, up ? base - hp : base,
                                           bw, hp, RAD, up), fill: "var(--thru)" }));
      }
    };
    stack(d.import_gwh ?? 0, true, "var(--out)");
    stack(d.export_gwh ?? 0, false, "var(--in)");'''
